class Solution {
  private int count;
  public int totalNQueens(int n) {
    count = 0;
    place(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
    return count;
  }
  private void place(int r, int n, boolean[] cols, boolean[] d1, boolean[] d2) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++) {
      int a = r - c + n, b = r + c;
      if (cols[c] || d1[a] || d2[b]) continue;
      cols[c] = d1[a] = d2[b] = true;
      place(r + 1, n, cols, d1, d2);
      cols[c] = d1[a] = d2[b] = false;
    }
  }
}

