import java.util.*;

class Solution {
  public boolean canPartitionKSubsets(int[] nums, int k) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % k != 0) return false;
    int target = total / k;
    int[] a = nums.clone();
    Arrays.sort(a);
    for (int i = 0, j = a.length - 1; i < j; i++, j--) { int t = a[i]; a[i] = a[j]; a[j] = t; }
    if (a[0] > target) return false;
    return bt(a, 0, new int[k], target);
  }
  private boolean bt(int[] a, int i, int[] buckets, int target) {
    if (i == a.length) return true;
    for (int b = 0; b < buckets.length; b++) {
      if (buckets[b] + a[i] > target) continue;
      buckets[b] += a[i];
      if (bt(a, i + 1, buckets, target)) return true;
      buckets[b] -= a[i];
      if (buckets[b] == 0) break;
    }
    return false;
  }
}

