import java.util.*;

class Solution {
  private Map<String, String> parent = new HashMap<>();
  private String find(String x) {
    while (!parent.get(x).equals(x)) { parent.put(x, parent.get(parent.get(x))); x = parent.get(x); }
    return x;
  }
  public List<List<String>> accountsMerge(List<List<String>> accounts) {
    Map<String, String> owner = new HashMap<>();
    for (List<String> acc : accounts) {
      for (int i = 1; i < acc.size(); i++) { parent.putIfAbsent(acc.get(i), acc.get(i)); owner.put(acc.get(i), acc.get(0)); }
      for (int i = 2; i < acc.size(); i++) parent.put(find(acc.get(i)), find(acc.get(1)));
    }
    Map<String, List<String>> groups = new HashMap<>();
    for (String e : parent.keySet()) groups.computeIfAbsent(find(e), k -> new ArrayList<>()).add(e);
    List<List<String>> res = new ArrayList<>();
    for (List<String> g : groups.values()) {
      Collections.sort(g);
      List<String> row = new ArrayList<>();
      row.add(owner.get(g.get(0)));
      row.addAll(g);
      res.add(row);
    }
    return res;
  }
}

