  for (const w of words) for (const c of w) { if (!adj.has(c)) { adj.set(c, new Set()); indeg.set(c, 0); } }
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i], b = words[i + 1];
    const len = Math.min(a.length, b.length);
    let j = 0;
    while (j < len && a[j] === b[j]) j++;
    if (j === len) { if (a.length > b.length) return ""; continue; }
    if (!adj.get(a[j]).has(b[j])) { adj.get(a[j]).add(b[j]); indeg.set(b[j], indeg.get(b[j]) + 1); }
  }
  const ready = [...indeg.keys()].filter(c => indeg.get(c) === 0);
  let out = "";
  while (ready.length) {
    ready.sort();
    const c = ready.shift();
    out += c;
    for (const d of adj.get(c)) { indeg.set(d, indeg.get(d) - 1); if (indeg.get(d) === 0) ready.push(d); }
  }
  return out.length === adj.size ? out : "";
}

